import math

class TicTacToe:
    def __init__(self):
        self.board = [' '] * 9
        self.nodes_generated = 0
        self.cutoffs = 0
        self.stage_stats = []

    def print_board(self):
        for i in range(0, 9, 3):
            print(f" {self.board[i]} | {self.board[i+1]} | {self.board[i+2]} ")
            if i < 6: print("---+---+---")
        print()

    def check_winner(self):
        win_states = [(0,1,2), (3,4,5), (6,7,8), (0,3,6), (1,4,7), (2,5,8), (0,4,8), (2,4,6)]
        for a, b, c in win_states:
            if self.board[a] == self.board[b] == self.board[c] != ' ':
                return self.board[a]
        if ' ' not in self.board:
            return 'Draw'
        return None

    def minimax(self, depth, is_maximizing, alpha, beta):
        self.nodes_generated += 1
        winner = self.check_winner()

        if winner == 'X': return 10 - depth
        if winner == 'O': return depth - 10
        if winner == 'Draw': return 0

        if is_maximizing:
            max_eval = -math.inf
            for i in range(9):
                if self.board[i] == ' ':
                    self.board[i] = 'X'
                    eval = self.minimax(depth + 1, False, alpha, beta)
                    self.board[i] = ' '
                    max_eval = max(max_eval, eval)
                    alpha = max(alpha, eval)
                    if beta <= alpha:
                        self.cutoffs += 1
                        break
            return max_eval
        else:
            min_eval = math.inf
            for i in range(9):
                if self.board[i] == ' ':
                    self.board[i] = 'O'
                    eval = self.minimax(depth + 1, True, alpha, beta)
                    self.board[i] = ' '
                    min_eval = min(min_eval, eval)
                    beta = min(beta, eval)
                    if beta <= alpha:
                        self.cutoffs += 1
                        break
            return min_eval

    def best_move(self, player):
        self.nodes_generated = 0
        self.cutoffs = 0
        best_val = -math.inf if player == 'X' else math.inf
        move = -1

        for i in range(9):
            if self.board[i] == ' ':
                self.board[i] = player
                move_val = self.minimax(0, player == 'O', -math.inf, math.inf)
                self.board[i] = ' '

                if player == 'X' and move_val > best_val:
                    best_val, move = move_val, i
                elif player == 'O' and move_val < best_val:
                    best_val, move = move_val, i
        return move

    def play_game(self):
        current_player = 'X'
        stage = 1
        self.print_board()

        while not self.check_winner():
            print(f"--- Turn {stage} ---")

            if current_player == 'X':
                valid_move = False
                while not valid_move:
                    try:
                        move = int(input("Enter your move (0-8): "))
                        if 0 <= move <= 8 and self.board[move] == ' ':
                            valid_move = True
                        else:
                            print("Invalid move.")
                    except ValueError:
                        print("Invalid input.")
            else:
                move = self.best_move(current_player)
                self.stage_stats.append({
                    'Stage': stage,
                    'Player': 'AI (O)',
                    'Nodes': self.nodes_generated,
                    'Cutoffs': self.cutoffs
                })

            self.board[move] = current_player
            self.print_board()
            current_player = 'O' if current_player == 'X' else 'X'
            stage += 1

        winner = self.check_winner()
        if winner == 'Draw':
            print("Game Over. Draw!")
        else:
            print(f"Game Over. Winner: {winner}")

        self.display_statistics()

    def display_statistics(self):
        print("\n" + "="*45)
        print(f"{'Stage':<8} | {'Player':<8} | {'Nodes Gen':<10} | {'Cutoffs':<8}")
        print("-" * 45)
        for stat in self.stage_stats:
            print(f"{stat['Stage']:<8} | {stat['Player']:<8} | {stat['Nodes']:<10} | {stat['Cutoffs']:<8}")
        print("="*45)

